commands:
cat > /tmp/fleetcast-nginx.conf <<'EOF'
server {
  listen 80;
  server_name _;
  root /usr/share/nginx/html;
  index index.html;

  location /api/ {
    proxy_pass http://fleetcast-satellite-app-backend:5000;
    proxy_set_header Host $host;
    proxy_set_header X-Real-IP $remote_addr;
    proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    proxy_set_header X-Forwarded-Proto $scheme;
  }

  location ~* \.(js|css|json|png|jpg|jpeg|gif|ico|svg|woff|woff2|ttf|eot)$ {
    try_files $uri $uri/ /index.html;
    access_log off;
    expires 1y;
    add_header Cache-Control "public";
  }

  location / {
    try_files $uri /index.html;
  }
}
EOF
kubectl create configmap fleetcast-frontend-nginx -n fleetcast --from-file=default.conf=/tmp/fleetcast-nginx.conf --dry-run=client -o yaml | kubectl apply -f -
kubectl patch deployment fleetcast-satellite-app-frontend -n fleetcast --type=strategic -p '{"spec":{"template":{"spec":{"containers":[{"name":"frontend","volumeMounts":[{"name":"nginx-config","mountPath":"/etc/nginx/conf.d/default.conf","subPath":"default.conf","readOnly":true}]}],"volumes":[{"name":"nginx-config","configMap":{"name":"fleetcast-frontend-nginx"}}]}}}}'
kubectl rollout status deployment/fleetcast-satellite-app-frontend -n fleetcast --timeout=60s
